import AppKit
import SqueakMacCore
import SwiftUI

/// The thread duck (DESIGN.md §6.5): the brand's template duck (`brand/logo/png/duckThread.png`, generated by
/// `brand/logo/make-tray-icon.py` from the approved logo, never redrawn) tinted in the thread's own colour, picked
/// from its id (`ThreadDuck`). The agent's mark is a badge at the bottom-right corner; state marks stay beside it.
struct ThreadDuckView: View {
    let id: String
    var agent: String?
    var size: CGFloat = 18
    /// A Conductor chat's own marker, at the top-right corner (the agent badge has the bottom-right).
    var conductor = false
    @Environment(\.colorScheme) private var scheme

    @MainActor private static var image: NSImage? = {
        guard let i = BrandAssets.image("duckThread.png") else { return nil }
        i.isTemplate = true
        return i
    }()

    var body: some View {
        let rgb = ThreadDuck.rgb(for: id, dark: scheme == .dark)
        Group {
            if let image = Self.image {
                Image(nsImage: image).renderingMode(.template).resizable().interpolation(.high).scaledToFit()
                    .foregroundStyle(Color(red: rgb.r, green: rgb.g, blue: rgb.b))
            } else {
                Color.clear
            }
        }
        .frame(width: size, height: size)
        .overlay(alignment: .bottomTrailing) {
            if let badge = AgentMark(agent: agent, size: ThreadDuck.badgeSize(duck: size)) {
                badge
                    .background(Theme.surface, in: Circle().inset(by: -1))
                    .offset(x: size * ThreadDuck.badgeOffsetFraction, y: size * ThreadDuck.badgeOffsetFraction)
            }
        }
        .overlay(alignment: .topTrailing) {
            if conductor {
                AgentMark(.conductor, size: ThreadDuck.badgeSize(duck: size))
                    .background(Theme.surface, in: Circle().inset(by: -1))
                    .offset(x: size * ThreadDuck.badgeOffsetFraction, y: -size * ThreadDuck.badgeOffsetFraction)
            }
        }
        .accessibilityHidden(true)
    }
}

/// A subagent: a smaller duck in its parent thread's colour (no agent badge).
struct DucklingView: View {
    let parentId: String
    var parentSize: CGFloat = 18
    var body: some View {
        ThreadDuckView(id: parentId, size: ThreadDuck.ducklingSize(parent: parentSize))
    }
}
